syntax:
class Shape {
public:
    virtual double area() const = 0; // Hàm thuần ảo (Pure virtual)
    virtual ~Shape() {}              // Virtual destructor bắt buộc
};
class Circle : public Shape {
public:
    double area() const override { return 3.14; }
};

